-- Original Eego starter. Apply only after the deployment/import block is resolved.
-- Idempotent, additive seed: existing lessons and learning history are not overwritten.
DO $seed$
DECLARE d jsonb := $eego${"items": [{"id": "v.achieve", "kind": "vocabulary", "level": "B1", "label": "achieve", "meaning_ja": "達成する", "notes_ja": "achieve a goal は「目標を達成する」。努力の結果として成果や成功を得るときに使います。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "With regular practice, you can achieve your goal of running five kilometres.", "ja": "定期的に練習すれば、5キロ走るという目標を達成できます。"}, {"en": "After months of work, the team finally achieved the results it had hoped for.", "ja": "数か月の努力の末、チームはついに期待していた成果を達成しました。"}]}, {"id": "v.afford", "kind": "vocabulary", "level": "B1", "label": "afford", "meaning_ja": "経済的・時間的な余裕がある", "notes_ja": "can afford + 名詞 / to不定詞。「費用などを負担できる」という意味です。否定形では「〜する余裕がない」。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "The rent is too high; I cannot afford to live there.", "ja": "家賃が高すぎて、そこに住む余裕がありません。"}, {"en": "We saved for a year so that we could afford a new washing machine.", "ja": "新しい洗濯機を買えるように、1年間貯金しました。"}]}, {"id": "v.avoid", "kind": "vocabulary", "level": "B1", "label": "avoid", "meaning_ja": "避ける", "notes_ja": "avoid + 名詞 / 動名詞。「avoid to do」ではなく「avoid doing」を使います。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "Leave early to avoid getting stuck in traffic.", "ja": "渋滞に巻き込まれないよう、早めに出発してください。"}, {"en": "She avoided looking at her phone during the interview.", "ja": "彼女は面接中にスマートフォンを見るのを避けました。"}]}, {"id": "v.borrow", "kind": "vocabulary", "level": "B1", "label": "borrow", "meaning_ja": "借りる", "notes_ja": "borrow something from someone は「人から物を借りる」。lend は逆方向の「貸す」です。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "May I borrow your umbrella? I will return it tomorrow.", "ja": "傘を借りてもいいですか。明日返します。"}, {"en": "I borrowed three books from the library yesterday.", "ja": "昨日、図書館で本を3冊借りました。"}]}, {"id": "v.improve", "kind": "vocabulary", "level": "B1", "label": "improve", "meaning_ja": "改善する・上達する", "notes_ja": "improve は他動詞でも自動詞でも使えます。「improve your English」は英語力を伸ばすことです。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "Reading every day can help you improve your vocabulary.", "ja": "毎日の読書は語彙力を伸ばす助けになります。"}, {"en": "Her pronunciation has improved considerably since last year.", "ja": "彼女の発音は去年から大きく上達しました。"}]}, {"id": "v.prefer", "kind": "vocabulary", "level": "B1", "label": "prefer", "meaning_ja": "より好む", "notes_ja": "prefer A to B は「BよりAを好む」。prefer の比較対象には通常 than ではなく to を使います。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "I prefer tea to coffee because coffee keeps me awake.", "ja": "コーヒーを飲むと眠れなくなるので、私はコーヒーよりお茶が好きです。"}, {"en": "She prefers walking to taking a crowded bus.", "ja": "彼女は混んだバスに乗るより歩くほうが好きです。"}]}, {"id": "v.acknowledge", "kind": "vocabulary", "level": "B2", "label": "acknowledge", "meaning_ja": "認める・受け取ったことを知らせる", "notes_ja": "acknowledge は事実や責任を認めるほか、連絡や書類の受領を知らせる意味でも使います。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "The manager finally acknowledged that the mistake was his responsibility.", "ja": "上司はついに、そのミスが自分の責任だと認めました。"}, {"en": "Please acknowledge receipt of this message by replying to it.", "ja": "このメッセージを受信したことを、返信でお知らせください。"}]}, {"id": "v.approach", "kind": "vocabulary", "level": "B2", "label": "approach · method", "meaning_ja": "取り組み方・方法", "notes_ja": "an approach to + 名詞 / 動名詞で「〜への取り組み方」。この項目では名詞の意味を練習します。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "We need a different approach to solving this problem.", "ja": "この問題を解決するには、別の取り組み方が必要です。"}, {"en": "Her practical approach helped the team turn an idea into a working product.", "ja": "彼女の実践的な取り組み方が、アイデアを動く製品にする助けとなりました。"}]}, {"id": "v.consequence", "kind": "vocabulary", "level": "B2", "label": "consequence", "meaning_ja": "結果・影響", "notes_ja": "as a consequence は「その結果」。consequence は行動や出来事から生じる結果を表します。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "A possible consequence of missing the deadline is losing the contract.", "ja": "締め切りに遅れると、契約を失う可能性があります。"}, {"en": "He ignored the warnings and had to face the consequences of his decision.", "ja": "彼は警告を無視したため、自分の決断の結果に向き合わなければなりませんでした。"}]}, {"id": "v.maintain", "kind": "vocabulary", "level": "B2", "label": "maintain", "meaning_ja": "維持する・手入れする", "notes_ja": "maintain は状態や水準を保つこと。設備を正常な状態に保つという意味もあります。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "It takes regular exercise to maintain a good level of fitness.", "ja": "良い体力水準を維持するには、定期的な運動が必要です。"}, {"en": "The machines must be properly maintained to prevent breakdowns.", "ja": "故障を防ぐには、機械を適切に整備しなければなりません。"}]}, {"id": "v.reluctant", "kind": "vocabulary", "level": "B2", "label": "reluctant", "meaning_ja": "気が進まない・消極的な", "notes_ja": "be reluctant to do は「〜する気が進まない」。完全な拒否ではなく、ためらいを表します。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "She was reluctant to lend him more money because he had not repaid the last loan.", "ja": "彼が前の借金を返していなかったため、彼女はさらにお金を貸すことに気が進みませんでした。"}, {"en": "He agreed to speak, but his reluctant tone suggested he would rather remain silent.", "ja": "彼は話すことに同意しましたが、その消極的な口調からは黙っていたい気持ちがうかがえました。"}]}, {"id": "v.resolve", "kind": "vocabulary", "level": "B2", "label": "resolve · solve", "meaning_ja": "解決する", "notes_ja": "resolve a problem / dispute は「問題・争いを解決する」。解決に至ることに重点があります。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "The two sides met to resolve their disagreement.", "ja": "双方は意見の相違を解決するために会いました。"}, {"en": "The technical issue was resolved before the presentation began.", "ja": "技術的な問題は発表が始まる前に解決されました。"}]}, {"id": "v.allocate", "kind": "vocabulary", "level": "C1", "label": "allocate", "meaning_ja": "割り当てる", "notes_ja": "allocate resources to a task は「作業に資源を割り当てる」。時間・予算・人員にも使います。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "The committee will allocate additional funds to the research project.", "ja": "委員会は研究プロジェクトに追加資金を割り当てます。"}, {"en": "We have allocated two hours for questions after the workshop.", "ja": "ワークショップの後、質問のために2時間を割り当てました。"}]}, {"id": "v.concede.admit", "kind": "vocabulary", "level": "C1", "label": "concede · admit", "meaning_ja": "しぶしぶ認める", "notes_ja": "concede that ... は、議論や証拠を受けて「〜だと認める」。譲歩するニュアンスがあります。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "After seeing the evidence, he had to concede that his estimate was wrong.", "ja": "証拠を見た後、彼は自分の見積もりが間違っていたと認めざるを得ませんでした。"}, {"en": "She conceded that the proposal had some merit, despite her initial objections.", "ja": "彼女は当初反対していましたが、その提案にも一定の価値があると認めました。"}]}, {"id": "v.concede.goals", "kind": "vocabulary", "level": "C1", "label": "concede · allow a goal", "meaning_ja": "失点する", "notes_ja": "スポーツで concede a goal / point は「ゴール・得点を相手に許す」。議論で認める意味とは区別します。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "The team conceded two goals in the final ten minutes.", "ja": "そのチームは最後の10分間に2失点しました。"}, {"en": "A strong defence helped the visitors avoid conceding a single goal.", "ja": "堅い守備のおかげで、アウェーチームは1点も失わずに済みました。"}]}, {"id": "v.compelling", "kind": "vocabulary", "level": "C1", "label": "compelling", "meaning_ja": "説得力のある・強く引きつける", "notes_ja": "compelling evidence / argument は「説得力のある証拠・主張」。物語が魅力的で目を離せない場合にも使います。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "The scientist presented compelling evidence that challenged the old theory.", "ja": "科学者は従来の理論に疑問を投げかける、説得力のある証拠を示しました。"}, {"en": "The novel was so compelling that I read it in one sitting.", "ja": "その小説は非常に引きつけられる内容で、私は一気に読みました。"}]}, {"id": "v.feasible", "kind": "vocabulary", "level": "C1", "label": "feasible", "meaning_ja": "実行可能な", "notes_ja": "feasible は条件や資源を考えて実行できること。「望ましい」ことと「実行可能」なことは別です。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "The plan is attractive, but it is not financially feasible.", "ja": "その計画は魅力的ですが、資金面では実行できません。"}, {"en": "We need to decide whether finishing the work by Friday is feasible.", "ja": "金曜日までに作業を終えることが実行可能か判断する必要があります。"}]}, {"id": "v.mitigate", "kind": "vocabulary", "level": "C1", "label": "mitigate", "meaning_ja": "悪影響・深刻さを和らげる", "notes_ja": "mitigate a risk / impact は「リスク・影響を軽減する」。完全に取り除くという意味とは限りません。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "The new flood barriers are designed to mitigate the impact of heavy rain.", "ja": "新しい防水壁は大雨の影響を軽減するために設計されています。"}, {"en": "Early action could have mitigated some of the damage.", "ja": "早く対応していれば、被害の一部を軽減できたかもしれません。"}]}, {"id": "v.equivocal", "kind": "vocabulary", "level": "C2", "label": "equivocal", "meaning_ja": "曖昧な・どちらとも取れる", "notes_ja": "equivocal は、意味や立場がはっきりせず複数の解釈ができること。明確な賛否を避ける返答などに使います。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "His equivocal reply left us unsure whether he supported the proposal.", "ja": "彼の曖昧な返答では、その提案を支持しているのか分かりませんでした。"}, {"en": "The experimental results were equivocal, so no firm conclusion could be drawn.", "ja": "実験結果ははっきりせず、確かな結論を出せませんでした。"}]}, {"id": "v.meticulous", "kind": "vocabulary", "level": "C2", "label": "meticulous", "meaning_ja": "細部まで非常に注意深い", "notes_ja": "meticulous attention to detail は「細部への細心の注意」。手順や作業の丁寧さを表します。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "Her meticulous records included the date, time and conditions of every measurement.", "ja": "彼女の綿密な記録には、すべての測定の日時と条件が含まれていました。"}, {"en": "The restoration required meticulous attention to the smallest details.", "ja": "修復には、最も細かな部分まで細心の注意を払う必要がありました。"}]}, {"id": "v.ostensibly", "kind": "vocabulary", "level": "C2", "label": "ostensibly", "meaning_ja": "表向きは・一見したところは", "notes_ja": "ostensibly は、公に示された目的や見かけが真の事情と異なる可能性を示します。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "He travelled there ostensibly for a conference, though his real purpose was to visit family.", "ja": "彼は表向きは会議のためにそこへ行きましたが、本当の目的は家族に会うことでした。"}, {"en": "The rule was ostensibly introduced for safety, but critics suspected another motive.", "ja": "その規則は表向きは安全のために導入されましたが、批判する人々は別の動機を疑いました。"}]}, {"id": "v.perfunctory", "kind": "vocabulary", "level": "C2", "label": "perfunctory", "meaning_ja": "おざなりの・形式的な", "notes_ja": "perfunctory は、関心や努力をほとんど払わず形だけ行うこと。丁寧で徹底した行為の反対です。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "He gave the document a perfunctory glance instead of reading it carefully.", "ja": "彼は書類を注意深く読む代わりに、おざなりに目を通しただけでした。"}, {"en": "Her apology sounded perfunctory, as though she only wanted to end the conversation.", "ja": "彼女の謝罪は、会話を終わらせたいだけのようで、形式的に聞こえました。"}]}, {"id": "v.tenuous", "kind": "vocabulary", "level": "C2", "label": "tenuous", "meaning_ja": "根拠・つながりが弱い", "notes_ja": "a tenuous link / claim は「弱いつながり・根拠の乏しい主張」。物理的な細さを表す場合もあります。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "The connection between the two events is too tenuous to support that conclusion.", "ja": "その2つの出来事のつながりは弱すぎて、その結論を裏づけられません。"}, {"en": "Their argument rests on a tenuous assumption that has never been tested.", "ja": "彼らの議論は、一度も検証されていない、根拠の弱い仮定に基づいています。"}]}, {"id": "v.ubiquitous", "kind": "vocabulary", "level": "C2", "label": "ubiquitous", "meaning_ja": "至る所にある", "notes_ja": "ubiquitous は、ある物がいたる所で見られること。単に「人気がある」という意味ではありません。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "Smartphones have become so ubiquitous that it is unusual to meet someone without one.", "ja": "スマートフォンは至る所に普及し、持っていない人に会うほうが珍しくなりました。"}, {"en": "The brand's ubiquitous logo appeared on buses, billboards and shop windows.", "ja": "そのブランドのロゴは、バスや看板、店の窓など至る所に見られました。"}]}, {"id": "g.present-perfect", "kind": "grammar", "level": "B1", "label": "Present perfect", "meaning_ja": "過去から現在につながる経験・状態", "notes_ja": "have / has + 過去分詞。since は起点を表し、現在まで続く状態に現在完了を使います。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "She has lived in this town since 2020 and still lives here.", "ja": "彼女は2020年から現在までこの町に住んでいます。"}, {"en": "I have seen that film three times so far.", "ja": "私はこれまでにその映画を3回見ました。"}]}, {"id": "g.second-conditional", "kind": "grammar", "level": "B1", "label": "Second conditional", "meaning_ja": "現在・未来の仮定", "notes_ja": "If + 過去形, would + 動詞の原形。現実とは異なる状況や実現可能性が低いことを想像します。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "If I had more free time, I would learn to play the piano.", "ja": "もっと自由な時間があれば、ピアノを習うのですが。"}, {"en": "If she lived closer, we would see each other more often.", "ja": "彼女がもっと近くに住んでいれば、もっと頻繁に会えるのですが。"}]}, {"id": "g.used-to", "kind": "grammar", "level": "B1", "label": "Used to", "meaning_ja": "以前はよく〜した・以前は〜だった", "notes_ja": "used to + 動詞の原形で、現在はそうではない過去の習慣や状態を表します。be used to doing「〜に慣れている」と区別します。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "I used to walk to school every day, but now I take the train.", "ja": "以前は毎日学校まで歩いていましたが、今は電車に乗っています。"}, {"en": "There used to be a cinema here before it became a supermarket.", "ja": "スーパーになる前、ここには映画館がありました。"}]}, {"id": "g.relative-clauses", "kind": "grammar", "level": "B1", "label": "Relative clauses", "meaning_ja": "名詞を説明する関係詞節", "notes_ja": "who は人、which は物を説明します。主格の関係代名詞は、後ろの節の主語の役割を果たします。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "The woman who lives next door is a doctor.", "ja": "隣に住んでいる女性は医師です。"}, {"en": "This is the machine which broke down yesterday.", "ja": "これが昨日故障した機械です。"}]}, {"id": "g.past-perfect", "kind": "grammar", "level": "B2", "label": "Past perfect", "meaning_ja": "過去のある時点より前の出来事", "notes_ja": "had + 過去分詞。2つの過去の出来事のうち、先に起きたことを明確にします。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "By the time we arrived at the station, the train had left.", "ja": "私たちが駅に着いたときには、電車はすでに出発していました。"}, {"en": "She could not open the door because she had left her key at work.", "ja": "職場に鍵を置いてきたため、彼女はドアを開けられませんでした。"}]}, {"id": "g.third-conditional", "kind": "grammar", "level": "B2", "label": "Third conditional", "meaning_ja": "実際には起きなかった過去の仮定", "notes_ja": "If + had + 過去分詞, would have + 過去分詞。過去の事実とは違う状況と、その結果を想像します。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "If I had known about the meeting, I would have attended.", "ja": "その会議について知っていれば、出席したのですが。"}, {"en": "If they had left earlier, they would have caught the bus.", "ja": "もっと早く出発していれば、彼らはバスに間に合ったのですが。"}]}, {"id": "g.passive", "kind": "grammar", "level": "B2", "label": "Present perfect passive", "meaning_ja": "現在完了の受動態", "notes_ja": "has / have been + 過去分詞。行為を受ける物や人を主語にして、完了したことなどを表します。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "The reports have been checked by the editor and are ready to publish.", "ja": "報告書は編集者による確認が済み、公開できる状態です。"}, {"en": "The bridge has been repaired, so it is open again.", "ja": "橋の修理が完了したため、再び通行できます。"}]}, {"id": "g.contrast", "kind": "grammar", "level": "B2", "label": "Although / despite", "meaning_ja": "対比・譲歩の接続", "notes_ja": "although の後ろは主語と動詞を含む節、despite の後ろは名詞や動名詞です。despite of とは言いません。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "Although it was raining heavily, the match continued.", "ja": "激しい雨が降っていたにもかかわらず、試合は続きました。"}, {"en": "Despite the heavy rain, the match continued.", "ja": "大雨にもかかわらず、試合は続きました。"}]}, {"id": "g.negative-inversion", "kind": "grammar", "level": "C1", "label": "Negative inversion", "meaning_ja": "否定表現を文頭に置く倒置", "notes_ja": "Never / Rarely などを文頭に置くと、助動詞 + 主語の語順になります。強調した書き言葉などで使います。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "Never have I seen such a beautiful night sky.", "ja": "これほど美しい夜空を見たことはありません。"}, {"en": "Rarely do we find a proposal that satisfies everyone.", "ja": "全員を満足させる提案が見つかることはめったにありません。"}]}, {"id": "g.mixed-conditional", "kind": "grammar", "level": "C1", "label": "Mixed conditional", "meaning_ja": "過去の仮定と現在の結果", "notes_ja": "If + had + 過去分詞, would + 原形は、過去の事実が違っていたら現在はどうなっているかを表します。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "If I had studied medicine, I would be a doctor now.", "ja": "医学を学んでいたら、今ごろ医師になっていたでしょう。"}, {"en": "If she had accepted the job offer last year, she would be living in London now.", "ja": "去年その内定を受けていたら、彼女は今ロンドンに住んでいるでしょう。"}]}, {"id": "g.cleft", "kind": "grammar", "level": "C1", "label": "It-cleft sentences", "meaning_ja": "特定の部分を強調する分裂文", "notes_ja": "It is / was + 強調部分 + that ...。文の一部を取り出して焦点を当てます。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "It was the noise that woke me up, not the light.", "ja": "私を起こしたのは光ではなく、音でした。"}, {"en": "It was yesterday that she finally received the letter.", "ja": "彼女がようやくその手紙を受け取ったのは昨日でした。"}]}, {"id": "g.modal-perfect", "kind": "grammar", "level": "C1", "label": "Modal perfect", "meaning_ja": "過去への推量・後悔", "notes_ja": "must have + 過去分詞は過去についての強い推量。should have + 過去分詞は、するべきだったのにしなかったことを表せます。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "The lights are off and nobody answers. They must have gone home already.", "ja": "明かりは消え、返事もありません。彼らはもう帰宅したに違いありません。"}, {"en": "You should have told me before changing the schedule.", "ja": "予定を変える前に、私に知らせるべきでした。"}]}, {"id": "g.inverted-conditional", "kind": "grammar", "level": "C2", "label": "Inverted conditionals", "meaning_ja": "if を省略した仮定の倒置", "notes_ja": "Had + 主語 + 過去分詞は If + 主語 + had + 過去分詞に相当します。形式的な文体で使われます。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "Had I known about the delay, I would have stayed at home.", "ja": "遅延について知っていれば、家にいたのですが。"}, {"en": "Had the team prepared more carefully, it would have avoided the error.", "ja": "チームがもっと慎重に準備していれば、そのミスを避けられたでしょう。"}]}, {"id": "g.concessive-as", "kind": "grammar", "level": "C2", "label": "Concessive as", "meaning_ja": "形容詞を前に出す譲歩", "notes_ja": "形容詞 + as + 主語 + 動詞で「〜だけれども」。Tired as she was は Although she was tired に相当します。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "Tired as she was, she stayed to finish the work.", "ja": "彼女は疲れていましたが、仕事を終えるために残りました。"}, {"en": "Difficult as the task seemed, they decided to attempt it.", "ja": "その課題は難しそうでしたが、彼らは挑戦することにしました。"}]}, {"id": "g.not-until", "kind": "grammar", "level": "C2", "label": "Not until inversion", "meaning_ja": "「〜して初めて」の倒置", "notes_ja": "Not until ... を文頭に置く場合、倒置するのは主節です。until 節の語順は通常のままです。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "Not until I reached home did I realise that my wallet was missing.", "ja": "家に着いて初めて、財布がないことに気づきました。"}, {"en": "Not until the report was published did we understand the full extent of the problem.", "ja": "報告書が公開されて初めて、私たちは問題の全容を理解しました。"}]}, {"id": "g.perfect-participle", "kind": "grammar", "level": "C2", "label": "Perfect participle clauses", "meaning_ja": "主節より前の動作を表す分詞構文", "notes_ja": "Having + 過去分詞は、主節より先に完了した動作を示します。分詞構文と主節の意味上の主語は通常同じです。", "source": "Original Eego starter; CEFR band is an editorial estimate", "examples": [{"en": "Having finished the report, she sent it to her manager.", "ja": "報告書を書き終えてから、彼女はそれを上司に送りました。"}, {"en": "Having considered all the options, we chose the least expensive one.", "ja": "すべての選択肢を検討したうえで、最も安いものを選びました。"}]}], "questions": [{"item_id": "v.achieve", "sentence": "With regular practice, you can ____ your goal of running five kilometres.", "options": ["achieve", "borrow", "spill", "postpone"], "answer": "achieve", "hint_ja": "達成する", "explanation_ja": "achieve a goal は「目標を達成する」。努力の結果として成果や成功を得るときに使います。", "translation_ja": "定期的に練習すれば、5キロ走るという目標を達成できます。", "source": "Original Eego starter", "fingerprint": "6a82397b12ce018a4623727801113807823e29cb5ce78666813ecea5d7a6adde"}, {"item_id": "v.achieve", "sentence": "After months of work, the team finally ____ the results it had hoped for.", "options": ["achieved", "lent", "spilled", "mislaid"], "answer": "achieved", "hint_ja": "達成する", "explanation_ja": "achieve a goal は「目標を達成する」。努力の結果として成果や成功を得るときに使います。", "translation_ja": "数か月の努力の末、チームはついに期待していた成果を達成しました。", "source": "Original Eego starter", "fingerprint": "8b65dda847884978eeb004b71b90cec880c1f26b24c687cdc2d1ee731728966e"}, {"item_id": "v.afford", "sentence": "The rent is too high; I cannot ____ to live there.", "options": ["afford", "borrow", "invite", "repair"], "answer": "afford", "hint_ja": "経済的・時間的な余裕がある", "explanation_ja": "can afford + 名詞 / to不定詞。「費用などを負担できる」という意味です。否定形では「〜する余裕がない」。", "translation_ja": "家賃が高すぎて、そこに住む余裕がありません。", "source": "Original Eego starter", "fingerprint": "9d7f468eee34e69991e10b8c715ad1ea26ebc87c74b60a8a57f8791e09889808"}, {"item_id": "v.afford", "sentence": "We saved for a year so that we could ____ a new washing machine.", "options": ["afford", "spill", "interrupt", "lend"], "answer": "afford", "hint_ja": "経済的・時間的な余裕がある", "explanation_ja": "can afford + 名詞 / to不定詞。「費用などを負担できる」という意味です。否定形では「〜する余裕がない」。", "translation_ja": "新しい洗濯機を買えるように、1年間貯金しました。", "source": "Original Eego starter", "fingerprint": "86f799eb0a83a7ada32f0e0490851764e7123e37c7853f380fa91004c966ad6c"}, {"item_id": "v.avoid", "sentence": "Leave early to ____ getting stuck in traffic.", "options": ["avoid", "borrow", "lend", "afford"], "answer": "avoid", "hint_ja": "避ける", "explanation_ja": "avoid + 名詞 / 動名詞。「avoid to do」ではなく「avoid doing」を使います。", "translation_ja": "渋滞に巻き込まれないよう、早めに出発してください。", "source": "Original Eego starter", "fingerprint": "fd4d6b8f7aae1c1dae0b8c9a912c52aaa8d7e1d6ad8ca4f9b40c7868b04934a4"}, {"item_id": "v.avoid", "sentence": "She ____ looking at her phone during the interview.", "options": ["avoided", "repaired", "borrowed", "lent"], "answer": "avoided", "hint_ja": "避ける", "explanation_ja": "avoid + 名詞 / 動名詞。「avoid to do」ではなく「avoid doing」を使います。", "translation_ja": "彼女は面接中にスマートフォンを見るのを避けました。", "source": "Original Eego starter", "fingerprint": "11acb5c1240b0f696421223066593279360acda9a40029e084a5c52377d7ffcb"}, {"item_id": "v.borrow", "sentence": "May I ____ your umbrella? I will return it tomorrow.", "options": ["borrow", "lend", "achieve", "avoid"], "answer": "borrow", "hint_ja": "借りる", "explanation_ja": "borrow something from someone は「人から物を借りる」。lend は逆方向の「貸す」です。", "translation_ja": "傘を借りてもいいですか。明日返します。", "source": "Original Eego starter", "fingerprint": "70dfee7b4d707f7e3a119e313a546b6bb3ce6f93a5446dfb79aee460e71c1845"}, {"item_id": "v.borrow", "sentence": "I ____ three books from the library yesterday.", "options": ["borrowed", "lent", "achieved", "avoided"], "answer": "borrowed", "hint_ja": "借りる", "explanation_ja": "borrow something from someone は「人から物を借りる」。lend は逆方向の「貸す」です。", "translation_ja": "昨日、図書館で本を3冊借りました。", "source": "Original Eego starter", "fingerprint": "10fc3c177b6ad996ba3bee28aa4bc49d87a331f8fc9d1096c0b4467e6d22bd13"}, {"item_id": "v.improve", "sentence": "Reading every day can help you ____ your vocabulary.", "options": ["improve", "spill", "lend", "interrupt"], "answer": "improve", "hint_ja": "改善する・上達する", "explanation_ja": "improve は他動詞でも自動詞でも使えます。「improve your English」は英語力を伸ばすことです。", "translation_ja": "毎日の読書は語彙力を伸ばす助けになります。", "source": "Original Eego starter", "fingerprint": "7ddf57fa71603094945ad185118c47e2ec21afea87a4befc13a001d7f8dd27ad"}, {"item_id": "v.improve", "sentence": "Her pronunciation has ____ considerably since last year.", "options": ["improved", "borrowed", "lent", "spilled"], "answer": "improved", "hint_ja": "改善する・上達する", "explanation_ja": "improve は他動詞でも自動詞でも使えます。「improve your English」は英語力を伸ばすことです。", "translation_ja": "彼女の発音は去年から大きく上達しました。", "source": "Original Eego starter", "fingerprint": "5757152a73b614b5ee959fac6515c70972244f652c54939d0b4432a4a1283a1f"}, {"item_id": "v.prefer", "sentence": "I ____ tea to coffee because coffee keeps me awake.", "options": ["prefer", "repair", "lend", "achieve"], "answer": "prefer", "hint_ja": "より好む", "explanation_ja": "prefer A to B は「BよりAを好む」。prefer の比較対象には通常 than ではなく to を使います。", "translation_ja": "コーヒーを飲むと眠れなくなるので、私はコーヒーよりお茶が好きです。", "source": "Original Eego starter", "fingerprint": "4806411b3ccab4b95e9feb501c47dc5e904e3ded5d0758d31cca97cbefcde19d"}, {"item_id": "v.prefer", "sentence": "She ____ walking to taking a crowded bus.", "options": ["prefers", "borrows", "spills", "lends"], "answer": "prefers", "hint_ja": "より好む", "explanation_ja": "prefer A to B は「BよりAを好む」。prefer の比較対象には通常 than ではなく to を使います。", "translation_ja": "彼女は混んだバスに乗るより歩くほうが好きです。", "source": "Original Eego starter", "fingerprint": "a1ef2072eb8771ab7650909fc844086f2da61deb350c024eb769e54efd0bf0d7"}, {"item_id": "v.acknowledge", "sentence": "The manager finally ____ that the mistake was his responsibility.", "options": ["acknowledged", "borrowed", "mislaid", "spilled"], "answer": "acknowledged", "hint_ja": "認める・受け取ったことを知らせる", "explanation_ja": "acknowledge は事実や責任を認めるほか、連絡や書類の受領を知らせる意味でも使います。", "translation_ja": "上司はついに、そのミスが自分の責任だと認めました。", "source": "Original Eego starter", "fingerprint": "0936abff3ea5a6c813865be3d3131f1f5d05c06e66f0bf77cd56f1bca5f07011"}, {"item_id": "v.acknowledge", "sentence": "Please ____ receipt of this message by replying to it.", "options": ["acknowledge", "borrow", "achieve", "spill"], "answer": "acknowledge", "hint_ja": "認める・受け取ったことを知らせる", "explanation_ja": "acknowledge は事実や責任を認めるほか、連絡や書類の受領を知らせる意味でも使います。", "translation_ja": "このメッセージを受信したことを、返信でお知らせください。", "source": "Original Eego starter", "fingerprint": "bd730f4456cf7cc72c361a525169ef3552f3c0ba9c88fd32289e0938efb7bab3"}, {"item_id": "v.approach", "sentence": "We need a different ____ to solving this problem.", "options": ["approach", "receipt", "ceiling", "departure"], "answer": "approach", "hint_ja": "取り組み方・方法", "explanation_ja": "an approach to + 名詞 / 動名詞で「〜への取り組み方」。この項目では名詞の意味を練習します。", "translation_ja": "この問題を解決するには、別の取り組み方が必要です。", "source": "Original Eego starter", "fingerprint": "9266a07c0d726ed7c1d3fa267324705c8a819c0c38388477d438b08effe03a09"}, {"item_id": "v.approach", "sentence": "Her practical ____ helped the team turn an idea into a working product.", "options": ["approach", "receipt", "ceiling", "umbrella"], "answer": "approach", "hint_ja": "取り組み方・方法", "explanation_ja": "an approach to + 名詞 / 動名詞で「〜への取り組み方」。この項目では名詞の意味を練習します。", "translation_ja": "彼女の実践的な取り組み方が、アイデアを動く製品にする助けとなりました。", "source": "Original Eego starter", "fingerprint": "b186a9d8132a13f09081f5724b6e729c116e88b5d7eca7aa334130485499ee6f"}, {"item_id": "v.consequence", "sentence": "A possible ____ of missing the deadline is losing the contract.", "options": ["consequence", "ingredient", "receipt", "ceiling"], "answer": "consequence", "hint_ja": "結果・影響", "explanation_ja": "as a consequence は「その結果」。consequence は行動や出来事から生じる結果を表します。", "translation_ja": "締め切りに遅れると、契約を失う可能性があります。", "source": "Original Eego starter", "fingerprint": "198fa347bc4217e11f08f85b76c7c9f0d462767c0292ab943e283d0cc0c0b02a"}, {"item_id": "v.consequence", "sentence": "He ignored the warnings and had to face the ____ of his decision.", "options": ["consequences", "ingredients", "umbrellas", "receipts"], "answer": "consequences", "hint_ja": "結果・影響", "explanation_ja": "as a consequence は「その結果」。consequence は行動や出来事から生じる結果を表します。", "translation_ja": "彼は警告を無視したため、自分の決断の結果に向き合わなければなりませんでした。", "source": "Original Eego starter", "fingerprint": "a9694c3f14f8015bac52b5da3232e609276ea2626a093ffb31c92687c1415609"}, {"item_id": "v.maintain", "sentence": "It takes regular exercise to ____ a good level of fitness.", "options": ["maintain", "borrow", "spill", "postpone"], "answer": "maintain", "hint_ja": "維持する・手入れする", "explanation_ja": "maintain は状態や水準を保つこと。設備を正常な状態に保つという意味もあります。", "translation_ja": "良い体力水準を維持するには、定期的な運動が必要です。", "source": "Original Eego starter", "fingerprint": "c1c28ebed1fc8db086f20a9f6db79443d71b59f317d5a368ef69f86d776f118e"}, {"item_id": "v.maintain", "sentence": "The machines must be properly ____ to prevent breakdowns.", "options": ["maintained", "borrowed", "spilled", "forgotten"], "answer": "maintained", "hint_ja": "維持する・手入れする", "explanation_ja": "maintain は状態や水準を保つこと。設備を正常な状態に保つという意味もあります。", "translation_ja": "故障を防ぐには、機械を適切に整備しなければなりません。", "source": "Original Eego starter", "fingerprint": "b0d1c28cc8540e222b6355077293b86f0a0d9cfe21f39be97d521bf3c0c47c79"}, {"item_id": "v.reluctant", "sentence": "She was ____ to lend him more money because he had not repaid the last loan.", "options": ["reluctant", "identical", "rectangular", "fluent"], "answer": "reluctant", "hint_ja": "気が進まない・消極的な", "explanation_ja": "be reluctant to do は「〜する気が進まない」。完全な拒否ではなく、ためらいを表します。", "translation_ja": "彼が前の借金を返していなかったため、彼女はさらにお金を貸すことに気が進みませんでした。", "source": "Original Eego starter", "fingerprint": "72390a39c4c6ba096f690844f11da31a7903d4dcd83cd2dc4053d1dfefa0a113"}, {"item_id": "v.reluctant", "sentence": "He agreed to speak, but his ____ tone suggested he would rather remain silent.", "options": ["reluctant", "triangular", "identical", "wooden"], "answer": "reluctant", "hint_ja": "気が進まない・消極的な", "explanation_ja": "be reluctant to do は「〜する気が進まない」。完全な拒否ではなく、ためらいを表します。", "translation_ja": "彼は話すことに同意しましたが、その消極的な口調からは黙っていたい気持ちがうかがえました。", "source": "Original Eego starter", "fingerprint": "43a6f290e6df3692c118cd2cacf5d36487db35fa7f97f302bf2cf5ab0ad9da75"}, {"item_id": "v.resolve", "sentence": "The two sides met to ____ their disagreement.", "options": ["resolve", "borrow", "spill", "lend"], "answer": "resolve", "hint_ja": "解決する", "explanation_ja": "resolve a problem / dispute は「問題・争いを解決す